/*
 * CTAP2 MakeCredential (0x01), GetAssertion (0x02), GetNextAssertion (0x08).
 *
 * Backed by TROPIC01 ECC slots via credstore.h. The private keys
 * generated by lt_ecc_key_generate live entirely on the secure element;
 * STM32 firmware never sees them, signs them, or stores them.
 *
 * Phase 9 M3 rewrite: requests are parsed by ctap2_parse.c (chip-free,
 * host-tested); the steps follow CTAP 2.1 §6.1.2 / §6.2.2 / §6.3 for an
 * authenticator with clientPin and pinUvAuthToken, no built-in UV, no
 * credProtect, no enterprise attestation:
 *
 *   - a credential is used only for the RP it was made for;
 *   - discoverable (rk) credentials are real: GetAssertion without an
 *     allowList returns them newest first, with GetNextAssertion;
 *   - pinUvAuthParam needs a token with the mc / ga permission and a
 *     matching permissions RP ID; a touch-tested operation consumes it;
 *   - signCount: MakeCredential reads it, every assertion reserves the
 *     next value before signing (credstore.c).
 *
 * Authenticator-data layout (WebAuthn §6.5.1):
 *
 *   offset  size   field
 *      0    32     rpIdHash (SHA-256 of rpId)
 *     32     1     flags  UP 0x01, UV 0x04, AT 0x40, ED 0x80
 *     33     4     signCount (big-endian)
 *     37   var     attestedCredentialData (MakeCredential only)
 *                    aaguid 16 B (zero: "none" attestation), credIdLen 2 B,
 *                    credId 18 B, credPubKey (COSE_Key)
 *    ...   var     extensions (if ED)
 *
 * Signature input = authData || clientDataHash.
 */

#include "ctap2.h"
#include "ctap2_parse.h"
#include "credstore.h"
#include "slots.h"
#include "cbor.h"
#include "pin.h"
#include "pin_token.h"
#include "user_presence.h"

#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <assert.h>

#include "sha2.h"
#include "stm32u5xx_hal.h"   /* HAL_GetTick: token and GetNextAssertion timers */

/* Worst-case COSE_Key size for the keys we encode (Ed25519 OKP = 46 B). */
#define COSE_KEY_MAX  96u

#define FLAG_UP  0x01u
#define FLAG_UV  0x04u
#define FLAG_AT  0x40u
#define FLAG_ED  0x80u

#define UP_TIMEOUT_MS          30000u
#define GET_NEXT_TIMEOUT_MS    30000u   /* CTAP §6.3 step 3 */

#define TRY(expr) do { int rc_ = (expr); if (rc_ != 0) return rc_; } while (0)

/* ----- Helpers ----- */

static int status(uint8_t *resp, int code)
{
    resp[0] = (uint8_t) code;
    return 1;
}

static void be32_store(uint8_t *p, uint32_t v)
{
    p[0] = (uint8_t)(v >> 24);
    p[1] = (uint8_t)(v >> 16);
    p[2] = (uint8_t)(v >>  8);
    p[3] = (uint8_t) v;
}

/* COSE_Key for an Ed25519 public key: { 1: 1 (OKP), 3: -8 (EdDSA),
 * -1: 6 (Ed25519), -2: x }.  Keys already in canonical order. */
static int build_cose_ed25519(const uint8_t *pubkey, uint8_t *out, size_t out_max)
{
    cbor_writer_t w;
    cbor_writer_init(&w, out, out_max);
    cbor_write_map_header(&w, 4);
    cbor_write_uint(&w, 1);   cbor_write_uint(&w, 1);
    cbor_write_uint(&w, 3);   cbor_write_negint(&w, -8);
    cbor_write_negint(&w, -1); cbor_write_uint(&w, 6);
    cbor_write_negint(&w, -2); cbor_write_byte_string(&w, pubkey, CREDSTORE_PUBKEY_LEN);
    if (cbor_writer_error(&w)) return -1;
    return (int) cbor_writer_len(&w);
}

static int build_authdata(const uint8_t *rp_id_hash, uint8_t flags,
                          uint32_t sign_count,
                          const uint8_t *cred_id, size_t cred_id_len,
                          const uint8_t *cose_pubkey, size_t cose_pubkey_len,
                          uint8_t *out, size_t out_max)
{
    size_t need = 37u;
    int have_at = (flags & FLAG_AT) != 0;
    if (have_at) {
        need += 16u + 2u + cred_id_len + cose_pubkey_len;
    }
    if (need > out_max) return -1;

    size_t off = 0;
    memcpy(&out[off], rp_id_hash, 32); off += 32u;
    out[off++] = flags;
    be32_store(&out[off], sign_count); off += 4u;

    if (have_at) {
        /* AAGUID MUST be zero with self/none attestation (CTAP2.1
         * §6.4.3, WebAuthn L2 §8.2); strict RPs (Proton) reject a
         * branded one.  GetInfo still reports NIXTROPIC_AAGUID. */
        memset(&out[off], 0, 16); off += 16u;
        out[off++] = (uint8_t)(cred_id_len >> 8);
        out[off++] = (uint8_t) cred_id_len;
        memcpy(&out[off], cred_id, cred_id_len); off += cred_id_len;
        memcpy(&out[off], cose_pubkey, cose_pubkey_len); off += cose_pubkey_len;
    }
    return (int) off;
}

/* ----- Steps shared by MakeCredential and GetAssertion ----- */

static int wait_touch(void)
{
    /* H5 sign-canary: compare against UP_OK explicitly. */
    up_result_t up = user_presence_check(UP_TIMEOUT_MS);
    if (up == UP_OK) return 0;
    return (up == UP_CANCEL) ? (int) CTAP2_ERR_KEEPALIVE_CANCEL
                             : (int) CTAP2_ERR_OPERATION_DENIED;
}

/* Step 1: a zero-length pinUvAuthParam asks "touch the key you mean"
 * (CTAP2.0 platforms with several keys attached). */
static int pin_probe(void)
{
    TRY(wait_touch());
    return pin_is_set() ? (int) CTAP2_ERR_PIN_INVALID : (int) CTAP2_ERR_PIN_NOT_SET;
}

/* Step 2: a pinUvAuthParam needs a supported pinUvAuthProtocol. */
static int check_pin_uv_protocol(const ctap2_pin_uv_t *pu)
{
    if (!pu->has_param) return 0;
    if (pu->protocol == CTAP2_OPT_ABSENT) return (int) CTAP2_ERR_MISSING_PARAMETER;
    if (pu->protocol != (int) PIN_PROTOCOL_VERSION) return (int) CTAP1_ERR_INVALID_PARAMETER;
    return 0;
}

/* The token behind pinUvAuthParam must verify over clientDataHash, still
 * carry userVerified and the permission, and be bound to this RP or to
 * none (then it is bound now).  Every failure is PIN_AUTH_INVALID. */
static int check_token(const ctap2_pin_uv_t *pu, const uint8_t client_hash[32],
                       uint8_t perm, const uint8_t rp_hash[32])
{
    if (puat_verify(pu->param, pu->param_len, client_hash, 32, HAL_GetTick()) != 0
        || !puat_user_verified()
        || !puat_has_perm(perm)
        || !puat_rp_matches(rp_hash)) {
        return (int) CTAP2_ERR_PIN_AUTH_INVALID;
    }
    puat_bind_rp(rp_hash);
    return 0;
}

/* ===== MakeCredential (CTAP §6.1.2) ===== */

/* Steps 6-8 and 11.  makeCredUvNotRqd = !alwaysUv (GetInfo): with a PIN
 * set, only a non-discoverable credential may be made without a token. */
static int mc_uv_policy(const ctap2_mc_req_t *q, int rk,
                        const uint8_t rp_hash[32], uint8_t *uv_flag)
{
    int pin_set = pin_is_set();
    *uv_flag = 0;
    if (slots_force_uv_get()) {
        if (!pin_set || !q->pin_uv.has_param) return (int) CTAP2_ERR_PUAT_REQUIRED;
    } else if (pin_set && !q->pin_uv.has_param && rk) {
        return (int) CTAP2_ERR_PUAT_REQUIRED;
    }
    if (pin_set && q->pin_uv.has_param) {
        TRY(check_token(&q->pin_uv, q->client_hash, PUAT_PERM_MC, rp_hash));
        *uv_flag = FLAG_UV;
    }
    return 0;
}

/* Step 12: a listed credential of this RP already lives here.  The user
 * is asked to touch first, whatever they do, then the answer is
 * CREDENTIAL_EXCLUDED (CTAP2 behaves like U2F here). */
static int mc_excluded(const ctap2_mc_req_t *q, const uint8_t rp_hash[32])
{
    ctap2_cred_iter_t it;
    const uint8_t *id;
    size_t id_len;
    ctap2_cred_iter_init(&it, &q->exclude);
    while (ctap2_cred_iter_next(&it, &id, &id_len)) {
        credstore_handle_t h;
        if (credstore_find(id, id_len, rp_hash, &h, NULL) == 0) {
            (void) user_presence_check(UP_TIMEOUT_MS);
            return 1;
        }
    }
    return 0;
}

/* One pass over the stored credentials: the next creation sequence, and
 * for rk the discoverable credentials of the same RP and user, which the
 * new one replaces (step 17.2).  Unreadable metadata counts as sequence
 * 0 and is never replaced. */
static void mc_scan(const ctap2_mc_req_t *q, const uint8_t rp_hash[32], int rk,
                    uint32_t *next_created, uint32_t *replace_mask)
{
    uint32_t bitmap = slots_bitmap();
    uint32_t max = 0;
    *replace_mask = 0;
    for (int i = 0; i < (int) FIDO_SLOTS_MAX; ++i) {
        slot_meta_t m;
        if ((bitmap & (1u << i)) == 0u || slots_read_meta(i, &m) != 0) continue;
        if (m.created > max) max = m.created;
        if (rk && (m.flags & SLOTS_FLAG_RESIDENT)
            && memcmp(m.rp_id_hash, rp_hash, SLOTS_RP_ID_HASH_LEN) == 0
            && m.user_handle_len == q->user_id_len
            && memcmp(m.user_handle, q->user_id, q->user_id_len) == 0) {
            *replace_mask |= 1u << i;
        }
    }
    *next_created = (max == UINT32_MAX) ? max : max + 1u;
}

/* Attestation object, "none" format (Phase 6: strict RPs reject Ed25519
 * self-attestation in "packed").  authData carries credProps if asked. */
static int mc_respond(const ctap2_mc_req_t *q, const uint8_t rp_hash[32],
                      uint8_t flags, int rk, uint32_t sc,
                      const uint8_t pubkey[CREDSTORE_PUBKEY_LEN],
                      const uint8_t cred_id[CREDSTORE_CRED_ID_LEN],
                      uint8_t *resp, size_t resp_max)
{
    uint8_t cose_pub[COSE_KEY_MAX];
    int cose_len = build_cose_ed25519(pubkey, cose_pub, sizeof cose_pub);
    if (cose_len < 0) return status(resp, CTAP2_ERR_OTHER);

    uint8_t auth_data[256];
    if (q->want_cred_props) flags |= FLAG_ED;
    int ad_len = build_authdata(rp_hash, flags, sc, cred_id, CREDSTORE_CRED_ID_LEN,
                                cose_pub, (size_t) cose_len, auth_data, sizeof auth_data);
    if (ad_len < 0) return status(resp, CTAP2_ERR_OTHER);
    if (q->want_cred_props) {
        /* { "credProps": { "rk": <stored discoverability> } } */
        cbor_writer_t ew;
        cbor_writer_init(&ew, &auth_data[ad_len], sizeof auth_data - (size_t) ad_len);
        cbor_write_map_header(&ew, 1);
        cbor_write_text(&ew, "credProps");
        cbor_write_map_header(&ew, 1);
        cbor_write_text(&ew, "rk");
        cbor_write_bool(&ew, rk != 0);
        if (cbor_writer_error(&ew)) return status(resp, CTAP2_ERR_OTHER);
        ad_len += (int) cbor_writer_len(&ew);
    }

    resp[0] = CTAP2_OK;
    cbor_writer_t w;
    cbor_writer_init(&w, &resp[1], resp_max - 1u);
    cbor_write_map_header(&w, 3);
    cbor_write_uint(&w, 1); cbor_write_text(&w, "none");
    cbor_write_uint(&w, 2); cbor_write_byte_string(&w, auth_data, (size_t) ad_len);
    cbor_write_uint(&w, 3); cbor_write_map_header(&w, 0);
    if (cbor_writer_error(&w)) return status(resp, CTAP2_ERR_OTHER);
    return (int)(1u + cbor_writer_len(&w));
}

int ctap2_make_credential(const uint8_t *req, size_t req_len,
                          uint8_t *resp, size_t resp_max)
{
    ctap2_mc_req_t q;
    int rc = ctap2_parse_make_cred(req, req_len, &q);
    if (rc != 0) return status(resp, rc);

    if (q.pin_uv.has_param && q.pin_uv.param_len == 0u) return status(resp, pin_probe());
    if ((rc = check_pin_uv_protocol(&q.pin_uv)) != 0) return status(resp, rc);
    /* Step 5: no built-in UV, and MakeCredential always tests presence. */
    if (q.opt.uv == 1 || q.opt.up == 0) return status(resp, CTAP2_ERR_INVALID_OPTION);
    int rk = (q.opt.rk == 1);

    uint8_t rp_hash[32];
    sha256_Raw(q.rp_id, (uint32_t) q.rp_id_len, rp_hash);
    uint8_t uv_flag;
    if ((rc = mc_uv_policy(&q, rk, rp_hash, &uv_flag)) != 0) return status(resp, rc);

    /* H2 (Phase 6 M3): no MakeCredential while the store is mid-change. */
    if (credstore_is_mutating()) return status(resp, CTAP2_ERR_NOT_ALLOWED);
    if (mc_excluded(&q, rp_hash)) return status(resp, CTAP2_ERR_CREDENTIAL_EXCLUDED);

    /* Step 14: touch before a slot is used; then the token is spent. */
    if ((rc = wait_touch()) != 0) return status(resp, rc);
    puat_consume();

    uint32_t sc;
    if (credstore_signcount_peek(&sc) != 0) return status(resp, CTAP2_ERR_OTHER);
    uint32_t created, replace_mask;
    mc_scan(&q, rp_hash, rk, &created, &replace_mask);

    uint8_t pubkey[CREDSTORE_PUBKEY_LEN];
    uint8_t cred_id[CREDSTORE_CRED_ID_LEN];
    credstore_handle_t handle;
    rc = credstore_make(rp_hash, SLOTS_ALG_ED25519, rk ? SLOTS_FLAG_RESIDENT : 0u,
                        q.user_id, q.user_id_len, created, replace_mask,
                        pubkey, cred_id, &handle);
    if (rc == -1) return status(resp, CTAP2_ERR_KEY_STORE_FULL);
    if (rc != 0) return status(resp, CTAP2_ERR_OTHER);

    /* The replaced credentials stopped resolving with the bitmap write;
     * their keys go now.  A failed erase leaves a free slot holding an
     * old key, erased again before the slot is reused. */
    for (int i = 0; i < (int) FIDO_SLOTS_MAX; ++i) {
        if (replace_mask & (1u << i)) (void) credstore_erase_slot(i);
    }
    return mc_respond(&q, rp_hash, (uint8_t)(FLAG_UP | uv_flag | FLAG_AT), rk, sc,
                      pubkey, cred_id, resp, resp_max);
}

/* ===== GetAssertion (CTAP §6.2.2) and GetNextAssertion (§6.3) ===== */

/* Remembered between GetAssertion and GetNextAssertion; cleared by any
 * other command (dispatcher) and by a new GetAssertion. */
static struct {
    int      active;
    int8_t   slots[FIDO_SLOTS_MAX];
    int      count;
    int      pos;
    uint8_t  client_hash[32];
    uint8_t  rp_hash[32];
    uint8_t  flags;
    uint32_t last_ms;
} s_ga;

void ctap2_assertion_reset(void)
{
    memset(&s_ga, 0, sizeof s_ga);
}

/* Steps 5-6.  No token needed without alwaysUv; with one, uv is set. */
static int ga_uv_policy(const ctap2_ga_req_t *q, int up,
                        const uint8_t rp_hash[32], uint8_t *uv_flag)
{
    int pin_set = pin_is_set();
    *uv_flag = 0;
    if (slots_force_uv_get() && up) {
        if (!pin_set || !q->pin_uv.has_param) return (int) CTAP2_ERR_PUAT_REQUIRED;
    }
    if (pin_set && q->pin_uv.has_param) {
        TRY(check_token(&q->pin_uv, q->client_hash, PUAT_PERM_GA, rp_hash));
        *uv_flag = FLAG_UV;
    }
    return 0;
}

/* Step 7 with an allowList: the first listed credential that exists here
 * AND was made for this RP. */
static int ga_from_allow_list(const ctap2_ga_req_t *q, const uint8_t rp_hash[32])
{
    ctap2_cred_iter_t it;
    const uint8_t *id;
    size_t id_len;
    ctap2_cred_iter_init(&it, &q->allow);
    while (ctap2_cred_iter_next(&it, &id, &id_len)) {
        credstore_handle_t h;
        if (credstore_find(id, id_len, rp_hash, &h, NULL) == 0) {
            s_ga.slots[0] = (int8_t) h;
            return 1;
        }
    }
    return 0;
}

/* Step 7 without an allowList: the RP's discoverable credentials, newest
 * first (step 12.2.1); equal sequence numbers keep slot order. */
static int ga_discover(const uint8_t rp_hash[32])
{
    uint32_t created[FIDO_SLOTS_MAX];
    uint32_t bitmap = slots_bitmap();
    int n = 0;
    for (int i = 0; i < (int) FIDO_SLOTS_MAX; ++i) {
        slot_meta_t m;
        if ((bitmap & (1u << i)) == 0u || slots_read_meta(i, &m) != 0) continue;
        if (!(m.flags & SLOTS_FLAG_RESIDENT)
            || memcmp(m.rp_id_hash, rp_hash, SLOTS_RP_ID_HASH_LEN) != 0) continue;
        int j = n++;
        while (j > 0 && created[j - 1] < m.created) {
            created[j] = created[j - 1];
            s_ga.slots[j] = s_ga.slots[j - 1];
            --j;
        }
        created[j] = m.created;
        s_ga.slots[j] = (int8_t) i;
    }
    return n;
}

/* Reserve a signCount, sign authData || clientDataHash with the slot's
 * key, and answer.  number_of_creds > 1 adds numberOfCredentials. */
static int ga_sign_respond(int slot, const uint8_t rp_hash[32], uint8_t flags,
                           const uint8_t client_hash[32], int number_of_creds,
                           uint8_t *resp, size_t resp_max)
{
    slot_meta_t meta;
    uint32_t sc;
    if (slots_read_meta(slot, &meta) != 0 || credstore_signcount_next(&sc) != 0) {
        return status(resp, CTAP2_ERR_OTHER);
    }
    uint8_t sig_input[37 + 32];
    int ad_len = build_authdata(rp_hash, flags, sc, NULL, 0, NULL, 0,
                                sig_input, sizeof sig_input);
    if (ad_len < 0) return status(resp, CTAP2_ERR_OTHER);
    memcpy(&sig_input[ad_len], client_hash, 32);
    uint8_t sig[CREDSTORE_SIG_LEN];
    if (credstore_sign(slot, sig_input, (size_t) ad_len + 32u, sig) != 0) {
        return status(resp, CTAP2_ERR_OTHER);
    }

    uint8_t cred_id[SLOTS_CRED_ID_LEN];
    slots_make_cred_id(slot, &meta, cred_id);
    /* user.id is mandatory for a discoverable credential (§6.2 response). */
    int with_user = (meta.flags & SLOTS_FLAG_RESIDENT) && meta.user_handle_len > 0u;

    resp[0] = CTAP2_OK;
    cbor_writer_t w;
    cbor_writer_init(&w, &resp[1], resp_max - 1u);
    cbor_write_map_header(&w, 3u + (with_user ? 1u : 0u) + (number_of_creds > 1 ? 1u : 0u));
    cbor_write_uint(&w, 1);
    cbor_write_map_header(&w, 2);
    cbor_write_text(&w, "id");
    cbor_write_byte_string(&w, cred_id, sizeof cred_id);
    cbor_write_text(&w, "type");
    cbor_write_text(&w, "public-key");
    cbor_write_uint(&w, 2); cbor_write_byte_string(&w, sig_input, (size_t) ad_len);
    cbor_write_uint(&w, 3); cbor_write_byte_string(&w, sig, sizeof sig);
    if (with_user) {
        cbor_write_uint(&w, 4);
        cbor_write_map_header(&w, 1);
        cbor_write_text(&w, "id");
        cbor_write_byte_string(&w, meta.user_handle, meta.user_handle_len);
    }
    if (number_of_creds > 1) {
        cbor_write_uint(&w, 5);
        cbor_write_uint(&w, (uint64_t) number_of_creds);
    }
    if (cbor_writer_error(&w)) return status(resp, CTAP2_ERR_OTHER);
    return (int)(1u + cbor_writer_len(&w));
}

int ctap2_get_assertion(const uint8_t *req, size_t req_len,
                        uint8_t *resp, size_t resp_max)
{
    ctap2_assertion_reset();

    ctap2_ga_req_t q;
    int rc = ctap2_parse_get_assertion(req, req_len, &q);
    if (rc != 0) return status(resp, rc);

    if (q.pin_uv.has_param && q.pin_uv.param_len == 0u) return status(resp, pin_probe());
    if ((rc = check_pin_uv_protocol(&q.pin_uv)) != 0) return status(resp, rc);
    /* Step 4: no built-in UV; "rk" is not a GetAssertion option. */
    if (q.opt.uv == 1) return status(resp, CTAP2_ERR_INVALID_OPTION);
    if (q.opt.rk != CTAP2_OPT_ABSENT) return status(resp, CTAP2_ERR_UNSUPPORTED_OPTION);
    int up = (q.opt.up != 0);

    uint8_t rp_hash[32];
    sha256_Raw(q.rp_id, (uint32_t) q.rp_id_len, rp_hash);
    uint8_t uv_flag;
    if ((rc = ga_uv_policy(&q, up, rp_hash, &uv_flag)) != 0) return status(resp, rc);

    if (credstore_is_mutating()) return status(resp, CTAP2_ERR_NOT_ALLOWED);
    int count = q.allow.present ? ga_from_allow_list(&q, rp_hash) : ga_discover(rp_hash);
    if (count == 0) return status(resp, CTAP2_ERR_NO_CREDENTIALS);

    /* Step 9: up=false is a silent pre-flight (UP bit 0, no touch). */
    if (up) {
        if ((rc = wait_touch()) != 0) return status(resp, rc);
        puat_consume();
    }
    uint8_t flags = (uint8_t)((up ? FLAG_UP : 0u) | uv_flag);
    rc = ga_sign_respond(s_ga.slots[0], rp_hash, flags, q.client_hash,
                         q.allow.present ? 0 : count, resp, resp_max);
    if (resp[0] == CTAP2_OK && count > 1) {
        s_ga.active = 1;
        s_ga.count = count;
        s_ga.pos = 1;
        memcpy(s_ga.client_hash, q.client_hash, 32);
        memcpy(s_ga.rp_hash, rp_hash, 32);
        s_ga.flags = flags;
        s_ga.last_ms = HAL_GetTick();
    }
    return rc;
}

int ctap2_get_next_assertion(uint8_t *resp, size_t resp_max)
{
    if (!s_ga.active || s_ga.pos >= s_ga.count) return status(resp, CTAP2_ERR_NOT_ALLOWED);
    if (HAL_GetTick() - s_ga.last_ms > GET_NEXT_TIMEOUT_MS) {
        ctap2_assertion_reset();
        return status(resp, CTAP2_ERR_NOT_ALLOWED);
    }
    int slot = s_ga.slots[s_ga.pos++];
    s_ga.last_ms = HAL_GetTick();
    return ga_sign_respond(slot, s_ga.rp_hash, s_ga.flags, s_ga.client_hash, 0,
                           resp, resp_max);
}
